# PlatformIO extra script: web/upload.html into the firmware, gzipped, as
# upload_page.h (kUploadPage, kUploadPageSize) in the build folder, so the
# generated file stays out of git. Rewritten only when the page changed.

import gzip
import os

Import("env")  # noqa: F821 (provided by PlatformIO)

project = env.subst("$PROJECT_DIR")  # noqa: F821
out_dir = os.path.join(env.subst("$BUILD_DIR"), "generated")  # noqa: F821
page = os.path.join(project, "web", "upload.html")
header = os.path.join(out_dir, "upload_page.h")

data = gzip.compress(open(page, "rb").read(), compresslevel=9, mtime=0)
lines = [", ".join(f"0x{b:02x}" for b in data[i:i + 20]) for i in range(0, len(data), 20)]
text = (
    "// Generated by tools/embed_web.py from web/upload.html: don't edit\n"
    "#pragma once\n#include <stddef.h>\n#include <stdint.h>\n"
    f"static const uint8_t kUploadPage[] = {{\n    {(',' + chr(10) + '    ').join(lines)}\n}};\n"
    f"static const size_t kUploadPageSize = {len(data)};\n"
)
os.makedirs(out_dir, exist_ok=True)
if not os.path.exists(header) or open(header, encoding="utf-8").read() != text:
    with open(header, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print(f"embed_web: upload page, {len(data)} bytes gzipped")
env.Append(CPPPATH=[out_dir])  # noqa: F821
